+#![forbid(unsafe_code)]
+//! Multi-dimension breakdown grouping, sorting, cardinality flagging, and pagination.
+
+use std::cmp::Ordering;
+use std::collections::BTreeMap;
+
+use rotameter_core::cardinality::OVERFLOW_BUCKET;
+use rotameter_core::error::CoreError;
+use rotameter_core::id::SiteId;
+use rotameter_core::query::{Dimension, Metric, QueryFilter, QuerySort, SortDir};
+use rotameter_core::storage::BreakdownRow;
+use rusqlite::{Connection, params_from_iter, types::Value};
+
+use crate::config::map_sql_err;
+use crate::query::breakdown_sql::{build_event_breakdown_sql, build_session_breakdown_sql};
+use crate::query::dim_map::dimension_key_name;
+use crate::query::filter_sql::build_filter_plan;
+use crate::query::summary::{build_kpi_summary, non_neg_u64, u64_to_f64};
+
+pub(crate) struct BreakdownOutcome {
+    pub(crate) rows: Vec<BreakdownRow>,
+    pub(crate) total_rows: u64,
+    pub(crate) truncated_by_cardinality_cap: bool,
+}
+
+#[allow(clippy::too_many_arguments)]
+pub(crate) fn query_breakdown(
+    conn: &Connection,
+    site_id: SiteId,
+    from_ms: i64,
+    to_ms: i64,
+    group_by: &[Dimension],
+    filters: &[QueryFilter],
+    primary_metric: Metric,
+    sort: Option<&QuerySort>,
+    limit: u32,
+    offset: u32,
+) -> Result<BreakdownOutcome, CoreError> {
+    if group_by.is_empty() {
+        return Ok(BreakdownOutcome {
+            rows: Vec::new(),
+            total_rows: 0,
+            truncated_by_cardinality_cap: false,
+        });
+    }
+
+    let mut params = vec![
+        Value::Blob(site_id.as_bytes().to_vec()),
+        Value::Integer(from_ms),
+        Value::Integer(to_ms),
+    ];
+    let mut plan = build_filter_plan(filters, group_by, &mut params)?;
+    let dim_cols: Vec<(&'static str, &'static str, String)> = group_by
+        .iter()
+        .enumerate()
+        .map(|(i, dim)| {
+            (
+                dimension_key_name(*dim),
+                plan.ensure_dimension(*dim),
+                format!("k{i}"),
+            )
+        })
+        .collect();
+    let joins = plan.join_sql();
+    let where_tail = plan.where_sql();
+
+    let sql = if plan.needs_events {
+        build_event_breakdown_sql(&dim_cols, &joins, &where_tail)
+    } else {
+        build_session_breakdown_sql(&dim_cols, &joins, &where_tail)
+    };
+
+    let (mut rows, truncated) = read_breakdown_rows(conn, &sql, &params, &dim_cols)?;
+    let sort_metric = sort.map_or(primary_metric, |s| s.by);
+    let sort_dir = sort.map_or(SortDir::Desc, |s| s.dir);
+    rows.sort_by(|a, b| compare_rows(a, b, sort_metric, sort_dir));
+
+    let total_rows = u64::try_from(rows.len()).unwrap_or(u64::MAX);
+    let start = usize::try_from(offset)
+        .unwrap_or(usize::MAX)
+        .min(rows.len());
+    let take = usize::try_from(limit).unwrap_or(usize::MAX);
+    let sliced = rows.into_iter().skip(start).take(take).collect();
+
+    Ok(BreakdownOutcome {
+        rows: sliced,
+        total_rows,
+        truncated_by_cardinality_cap: truncated,
+    })
+}
+
+fn read_breakdown_rows(
+    conn: &Connection,
+    sql: &str,
+    params: &[Value],
+    dim_cols: &[(&'static str, &'static str, String)],
+) -> Result<(Vec<BreakdownRow>, bool), CoreError> {
+    let mut stmt = conn.prepare(sql).map_err(map_sql_err)?;
+    let mut cursor = stmt
+        .query(params_from_iter(params.iter()))
+        .map_err(map_sql_err)?;
+    let offset = dim_cols.len();
+    let mut out = Vec::new();
+    let mut truncated = false;
+
+    while let Some(row) = cursor.next().map_err(map_sql_err)? {
+        let mut key = BTreeMap::new();
+        for (idx, (dim_name, _, _)) in dim_cols.iter().enumerate() {
+            let val: String = row.get(idx).map_err(map_sql_err)?;
+            if val == OVERFLOW_BUCKET {
+                truncated = true;
+            }
+            key.insert((*dim_name).to_string(), val);
+        }
+        let visitors = non_neg_u64(row.get(offset).map_err(map_sql_err)?);
+        let pageviews = non_neg_u64(row.get(offset + 1).map_err(map_sql_err)?);
+        let visits = non_neg_u64(row.get(offset + 2).map_err(map_sql_err)?);
+        let bounced = non_neg_u64(row.get(offset + 3).map_err(map_sql_err)?);
+        let duration = non_neg_u64(row.get(offset + 4).map_err(map_sql_err)?);
+        let kpi = build_kpi_summary(visitors, pageviews, visits, bounced, duration);
+        out.push(BreakdownRow {
+            key,
+            visitors: kpi.visitors,
+            pageviews: kpi.pageviews,
+            visits: kpi.visits,
+            bounce_rate: kpi.bounce_rate,
+            avg_visit_duration_ms: kpi.avg_visit_duration_ms,
+        });
+    }
+    Ok((out, truncated))
+}
+
+fn compare_rows(a: &BreakdownRow, b: &BreakdownRow, metric: Metric, dir: SortDir) -> Ordering {
+    let ord = match metric {
+        Metric::Visitors => a.visitors.cmp(&b.visitors),
+        Metric::Pageviews => a.pageviews.cmp(&b.pageviews),
+        Metric::Visits => a.visits.cmp(&b.visits),
+        Metric::ViewsPerVisit => {
+            let av = u64_to_f64(a.pageviews) / u64_to_f64(a.visits.max(1));
+            let bv = u64_to_f64(b.pageviews) / u64_to_f64(b.visits.max(1));
+            av.total_cmp(&bv)
+        }
+        Metric::BounceRate => a.bounce_rate.total_cmp(&b.bounce_rate),
+        Metric::AvgVisitDurationMs => a.avg_visit_duration_ms.cmp(&b.avg_visit_duration_ms),
+    };
+    let directed = match dir {
+        SortDir::Asc => ord,
+        SortDir::Desc => ord.reverse(),
+    };
+    directed.then_with(|| a.key.cmp(&b.key))
+}
diff --git a/crates/rotameter-store-sqlite/src/query/breakdown_sql.rs b/crates/rotameter-store-sqlite/src/query/breakdown_sql.rs
new file mode 100644
index 0000000..e955901
--- /dev/null
+++ b/crates/rotameter-store-sqlite/src/query/breakdown_sql.rs
@@ -0,0 +1,74 @@
+#![forbid(unsafe_code)]
+//! Parameterized `SQL` builders for session-level and event-level breakdown queries.
+
+pub(crate) fn build_session_breakdown_sql(
+    dim_cols: &[(&'static str, &'static str, String)],
+    joins: &str,
+    where_tail: &str,
+) -> String {
+    let select_dims: Vec<String> = dim_cols
+        .iter()
+        .map(|(_, expr, alias)| format!("{expr} AS {alias}"))
+        .collect();
+    let group_aliases: Vec<&str> = dim_cols.iter().map(|(_, _, a)| a.as_str()).collect();
+    format!(
+        "SELECT {dims},
+                COUNT(DISTINCT s.visitor_id),
+                COALESCE(SUM(s.pageview_count), 0),
+                COUNT(*),
+                COALESCE(SUM(CASE WHEN s.event_count <= 1 THEN 1 ELSE 0 END), 0),
+                COALESCE(SUM(MAX(0, s.last_event_ms - s.started_at_ms)), 0)
+         FROM sessions s {joins}
+         WHERE s.site_id = ?1 AND s.started_at_ms >= ?2 AND s.started_at_ms < ?3 {where_tail}
+         GROUP BY {groups}",
+        dims = select_dims.join(", "),
+        groups = group_aliases.join(", "),
+    )
+}
+
+pub(crate) fn build_event_breakdown_sql(
+    dim_cols: &[(&'static str, &'static str, String)],
+    joins: &str,
+    where_tail: &str,
+) -> String {
+    let select_dims: Vec<String> = dim_cols
+        .iter()
+        .map(|(_, expr, alias)| format!("{expr} AS {alias}"))
+        .collect();
+    let group_aliases: Vec<&str> = dim_cols.iter().map(|(_, _, a)| a.as_str()).collect();
+    let alias_csv = group_aliases.join(", ");
+    format!(
+        "WITH matched AS (
+             SELECT {dims},
+                    e.visitor_id AS visitor_id,
+                    e.session_id AS session_id,
+                    CASE WHEN en_pv.value = 'pageview' THEN 1 ELSE 0 END AS is_pv,
+                    s.event_count AS event_count,
+                    MAX(0, s.last_event_ms - s.started_at_ms) AS dur_ms
+             FROM events e
+             JOIN sessions s ON s.site_id = e.site_id AND s.session_id = e.session_id
+             JOIN dim_strings en_pv ON en_pv.id = e.event_name_id
+             {joins}
+             WHERE e.site_id = ?1 AND e.ts_ms >= ?2 AND e.ts_ms < ?3 {where_tail}
+         ),
+         sess_agg AS (
+             SELECT {alias_csv},
+                    session_id,
+                    visitor_id,
+                    SUM(is_pv) AS pv_cnt,
+                    MAX(CASE WHEN event_count <= 1 THEN 1 ELSE 0 END) AS is_bounce,
+                    MAX(dur_ms) AS dur_ms
+             FROM matched
+             GROUP BY {alias_csv}, session_id
+         )
+         SELECT {alias_csv},
+                COUNT(DISTINCT visitor_id),
+                COALESCE(SUM(pv_cnt), 0),
+                COUNT(*),
+                COALESCE(SUM(is_bounce), 0),
+                COALESCE(SUM(dur_ms), 0)
+         FROM sess_agg
+         GROUP BY {alias_csv}",
+        dims = select_dims.join(", "),
+    )
+}
diff --git a/crates/rotameter-store-sqlite/src/query/csv.rs b/crates/rotameter-store-sqlite/src/query/csv.rs
new file mode 100644
index 0000000..07f18be
--- /dev/null
+++ b/crates/rotameter-store-sqlite/src/query/csv.rs
@@ -0,0 +1,139 @@
+#![forbid(unsafe_code)]
+//! `RFC 4180` CSV projection for [`QueryResult`] payloads.
+
+use rotameter_core::query::{Metric, QuerySpec};
+use rotameter_core::storage::{BreakdownRow, KpiSummary, QueryResult};
+
+use crate::query::dim_map::dimension_key_name;
+use crate::query::summary::u64_to_f64;
+
+/// Formats a [`QueryResult`] as an `RFC 4180` CSV string according to `spec`.
+///
+/// Exports breakdown rows when `spec.group_by` is non-empty, otherwise time-series
+/// buckets when `spec.granularity` is set, and otherwise the aggregate summary row.
+pub fn format_query_result_csv(result: &QueryResult, spec: &QuerySpec) -> String {
+    if !spec.group_by.is_empty() {
+        return format_breakdown_csv(result, spec);
+    }
+    if spec.granularity.is_some() {
+        return format_timeseries_csv(result);
+    }
+    format_summary_csv(&result.summary, &spec.metrics)
+}
+
+fn format_breakdown_csv(result: &QueryResult, spec: &QuerySpec) -> String {
+    let mut headers: Vec<&str> = spec
+        .group_by
+        .iter()
+        .map(|d| dimension_key_name(*d))
+        .collect();
+    headers.extend(spec.metrics.iter().map(|m| metric_header(*m)));
+
+    let mut out = String::new();
+    write_csv_line(&mut out, &headers);
+
+    for row in &result.rows {
+        let mut fields = Vec::with_capacity(headers.len());
+        for dim in &spec.group_by {
+            let key = dimension_key_name(*dim);
+            fields.push(row.key.get(key).cloned().unwrap_or_default());
+        }
+        for metric in &spec.metrics {
+            fields.push(format_breakdown_metric(row, *metric));
+        }
+        let refs: Vec<&str> = fields.iter().map(String::as_str).collect();
+        write_csv_line(&mut out, &refs);
+    }
+    out
+}
+
+fn format_timeseries_csv(result: &QueryResult) -> String {
+    let mut out = String::new();
+    write_csv_line(&mut out, &["bucket_ms", "visitors", "pageviews", "visits"]);
+    for point in &result.timeseries {
+        let b = point.bucket_ms.to_string();
+        let v = point.visitors.to_string();
+        let p = point.pageviews.to_string();
+        let s = point.visits.to_string();
+        write_csv_line(&mut out, &[&b, &v, &p, &s]);
+    }
+    out
+}
+
+fn format_summary_csv(summary: &KpiSummary, metrics: &[Metric]) -> String {
+    let headers: Vec<&str> = metrics.iter().map(|m| metric_header(*m)).collect();
+    let values: Vec<String> = metrics
+        .iter()
+        .map(|m| format_summary_metric(summary, *m))
+        .collect();
+    let refs: Vec<&str> = values.iter().map(String::as_str).collect();
+    let mut out = String::new();
+    write_csv_line(&mut out, &headers);
+    write_csv_line(&mut out, &refs);
+    out
+}
+
+const fn metric_header(metric: Metric) -> &'static str {
+    match metric {
+        Metric::Visitors => "visitors",
+        Metric::Pageviews => "pageviews",
+        Metric::Visits => "visits",
+        Metric::ViewsPerVisit => "views_per_visit",
+        Metric::BounceRate => "bounce_rate",
+        Metric::AvgVisitDurationMs => "avg_visit_duration_ms",
+    }
+}
+
+fn format_breakdown_metric(row: &BreakdownRow, metric: Metric) -> String {
+    match metric {
+        Metric::Visitors => row.visitors.to_string(),
+        Metric::Pageviews => row.pageviews.to_string(),
+        Metric::Visits => row.visits.to_string(),
+        Metric::ViewsPerVisit => {
+            let vpv = if row.visits == 0 {
+                0.0
+            } else {
+                u64_to_f64(row.pageviews) / u64_to_f64(row.visits)
+            };
+            format!("{vpv:.4}")
+        }
+        Metric::BounceRate => format!("{:.4}", row.bounce_rate),
+        Metric::AvgVisitDurationMs => row.avg_visit_duration_ms.to_string(),
+    }
+}
+
+fn format_summary_metric(summary: &KpiSummary, metric: Metric) -> String {
+    match metric {
+        Metric::Visitors => summary.visitors.to_string(),
+        Metric::Pageviews => summary.pageviews.to_string(),
+        Metric::Visits => summary.visits.to_string(),
+        Metric::ViewsPerVisit => format!("{:.4}", summary.views_per_visit),
+        Metric::BounceRate => format!("{:.4}", summary.bounce_rate),
+        Metric::AvgVisitDurationMs => summary.avg_visit_duration_ms.to_string(),
+    }
+}
+
+fn write_csv_line(out: &mut String, fields: &[&str]) {
+    for (idx, field) in fields.iter().enumerate() {
+        if idx > 0 {
+            out.push(',');
+        }
+        push_csv_field(out, field);
+    }
+    out.push('\n');
+}
+
+fn push_csv_field(out: &mut String, val: &str) {
+    if val.contains([',', '"', '\n', '\r']) {
+        out.push('"');
+        for ch in val.chars() {
+            if ch == '"' {
+                out.push('"');
+            }
+            out.push(ch);
+        }
+        out.push('"');
+    } else {
+        out.push_str(val);
+    }
+}
