new file mode 100644
index 0000000..b19edb1
--- /dev/null
+++ b/crates/rotameter-store-sqlite/src/query/filter_sql.rs
@@ -0,0 +1,120 @@
+#![forbid(unsafe_code)]
+//! Parameterized `SQL` join planner and predicate builder for `QueryFilter`.
+
+use rotameter_core::error::CoreError;
+use rotameter_core::query::{Dimension, FilterOp, FilterValue, QueryFilter};
+use rusqlite::types::Value;
+
+use crate::query::dim_map::dim_binding;
+
+pub(crate) struct SqlFilterPlan {
+    joins: Vec<(&'static str, &'static str)>,
+    clauses: Vec<String>,
+    pub(crate) needs_events: bool,
+}
+
+impl SqlFilterPlan {
+    pub(crate) fn ensure_dimension(&mut self, dim: Dimension) -> &'static str {
+        let binding = dim_binding(dim);
+        if binding.needs_events {
+            self.needs_events = true;
+        }
+        if let Some(join) = binding.join
+            && !self.joins.iter().any(|existing| existing.0 == join.0)
+        {
+            self.joins.push(join);
+        }
+        binding.expr
+    }
+
+    pub(crate) fn join_sql(&self) -> String {
+        let mut out = String::new();
+        for (alias, col) in &self.joins {
+            out.push_str(" JOIN dim_strings ");
+            out.push_str(alias);
+            out.push_str(" ON ");
+            out.push_str(alias);
+            out.push_str(".id = ");
+            out.push_str(col);
+        }
+        out
+    }
+
+    pub(crate) fn where_sql(&self) -> String {
+        let mut out = String::new();
+        for clause in &self.clauses {
+            out.push_str(" AND ");
+            out.push_str(clause);
+        }
+        out
+    }
+}
+
+pub(crate) fn build_filter_plan(
+    filters: &[QueryFilter],
+    group_by: &[Dimension],
+    params: &mut Vec<Value>,
+) -> Result<SqlFilterPlan, CoreError> {
+    let mut plan = SqlFilterPlan {
+        joins: Vec::new(),
+        clauses: Vec::new(),
+        needs_events: false,
+    };
+    for &dim in group_by {
+        plan.ensure_dimension(dim);
+    }
+    for filter in filters {
+        let expr = plan.ensure_dimension(filter.dimension);
+        let clause = build_predicate(expr, filter.op, &filter.value, params)?;
+        plan.clauses.push(clause);
+    }
+    Ok(plan)
+}
+
+fn build_predicate(
+    expr: &str,
+    op: FilterOp,
+    value: &FilterValue,
+    params: &mut Vec<Value>,
+) -> Result<String, CoreError> {
+    match (op, value) {
+        (FilterOp::Eq, FilterValue::Scalar(s)) => {
+            params.push(Value::Text(s.clone()));
+            Ok(format!("{expr} = ?{}", params.len()))
+        }
+        (FilterOp::Neq, FilterValue::Scalar(s)) => {
+            params.push(Value::Text(s.clone()));
+            Ok(format!("{expr} != ?{}", params.len()))
+        }
+        (FilterOp::In, FilterValue::List(items)) if !items.is_empty() => {
+            let mut placeholders = Vec::with_capacity(items.len());
+            for item in items {
+                params.push(Value::Text(item.clone()));
+                placeholders.push(format!("?{}", params.len()));
+            }
+            Ok(format!("{expr} IN ({})", placeholders.join(", ")))
+        }
+        (FilterOp::Contains, FilterValue::Scalar(s)) => {
+            params.push(Value::Text(format!("%{}%", escape_like(s))));
+            Ok(format!("{expr} LIKE ?{} ESCAPE '\\'", params.len()))
+        }
+        (FilterOp::Prefix, FilterValue::Scalar(s)) => {
+            params.push(Value::Text(format!("{}%", escape_like(s))));
+            Ok(format!("{expr} LIKE ?{} ESCAPE '\\'", params.len()))
+        }
+        _ => Err(CoreError::InvalidQuery(
+            "filter operator does not match operand value".to_string(),
+        )),
+    }
+}
+
+fn escape_like(input: &str) -> String {
+    let mut out = String::with_capacity(input.len());
+    for ch in input.chars() {
+        if matches!(ch, '\\' | '%' | '_') {
+            out.push('\\');
+        }
+        out.push(ch);
+    }
+    out
+}
diff --git a/crates/rotameter-store-sqlite/src/query/mod.rs b/crates/rotameter-store-sqlite/src/query/mod.rs
new file mode 100644
index 0000000..af3e741
--- /dev/null
+++ b/crates/rotameter-store-sqlite/src/query/mod.rs
@@ -0,0 +1,110 @@
+#![forbid(unsafe_code)]
+//! `SQLite` implementation of [`AnalyticsQueryStore`] and CSV formatting helpers.
+
+mod breakdown;
+mod breakdown_sql;
+pub mod csv;
+mod dim_map;
+mod filter_sql;
+mod rollup_summary;
+mod summary;
+mod timeseries;
+mod timeseries_rollup;
+mod window;
+
+use std::time::Instant;
+
+use rotameter_core::error::CoreError;
+use rotameter_core::id::SiteId;
+use rotameter_core::query::{Metric, QuerySpec};
+use rotameter_core::storage::{AnalyticsQueryStore, QueryMeta, QueryResult, RealtimeSnapshot};
+use rotameter_core::types::Site;
+
+pub use csv::format_query_result_csv;
+pub(crate) use summary::non_neg_u64;
+
+use self::breakdown::query_breakdown;
+use self::summary::query_summary;
+use self::timeseries::query_timeseries;
+use self::window::{parse_timezone, previous_window, resolve_window};
+use crate::realtime::query_realtime;
+use crate::retention::purge_site_before;
+use crate::store::SqliteStore;
+
+impl AnalyticsQueryStore for SqliteStore {
+    fn query(&self, site: &Site, spec: &QuerySpec, now_ms: i64) -> Result<QueryResult, CoreError> {
+        spec.validate()?;
+        let started = Instant::now();
+        let tz = parse_timezone(&site.timezone)?;
+
+        self.with_reader(|conn| {
+            let (from_ms, to_ms) = resolve_window(conn, site.site_id, &spec.range, tz, now_ms)?;
+            let summary = query_summary(conn, site.site_id, from_ms, to_ms, &spec.filters)?;
+
+            let previous_summary = if spec.compare_previous {
+                let (prev_from, prev_to) = previous_window(from_ms, to_ms);
+                Some(query_summary(
+                    conn,
+                    site.site_id,
+                    prev_from,
+                    prev_to,
+                    &spec.filters,
+                )?)
+            } else {
+                None
+            };
+
+            let timeseries = match spec.granularity {
+                Some(granularity) => query_timeseries(
+                    conn,
+                    site.site_id,
+                    from_ms,
+                    to_ms,
+                    granularity,
+                    tz,
+                    &spec.filters,
+                )?,
+                None => Vec::new(),
+            };
+
+            let primary_metric = spec.metrics.first().copied().unwrap_or(Metric::Visitors);
+            let breakdown = query_breakdown(
+                conn,
+                site.site_id,
+                from_ms,
+                to_ms,
+                &spec.group_by,
+                &spec.filters,
+                primary_metric,
+                spec.sort.as_ref(),
+                spec.limit,
+                spec.offset,
+            )?;
+
+            Ok(QueryResult {
+                site_id: site.site_id,
+                slug: site.slug.clone(),
+                timezone: site.timezone.clone(),
+                window_from_ms: from_ms,
+                window_to_ms: to_ms,
+                summary,
+                previous_summary,
+                timeseries,
+                rows: breakdown.rows,
+                meta: QueryMeta {
+                    total_rows: breakdown.total_rows,
+                    query_ms: started.elapsed().as_secs_f64() * 1_000.0,
+                    truncated_by_cardinality_cap: breakdown.truncated_by_cardinality_cap,
+                },
+            })
+        })
+    }
+
+    fn realtime(&self, site: &Site, now_ms: i64) -> Result<RealtimeSnapshot, CoreError> {
+        self.with_reader(|conn| query_realtime(conn, site, now_ms))
+    }
+
+    fn purge_before(&self, site_id: SiteId, before_ms: i64) -> Result<u64, CoreError> {
+        self.with_writer(|state| purge_site_before(&mut state.conn, site_id, before_ms))
+    }
+}
