+        Method::GET,
+        "/v1/pixel.gif?site=edge.dev&path=feed/rss.xml&ref=https%3A%2F%2Fnews.ycombinator.com%2F&event=rss_read",
+        None,
+        &[("cf-connecting-ip", "203.0.113.45"), ("cf-ipcountry", "CA")],
+        None,
