+  windowObj.self = windowObj;
+  vm.createContext(windowObj);
+  vm.runInContext(COLLECTOR_SRC, windowObj);
+
+  return {
+    window: windowObj,
+    document,
+    history,
+    locationObj,
+    beacons,
+    fetches,
+    get cookieWrites() { return cookieWrites; },
+    storageSetCalls,
+  };
+}
